# Verify the HTML can be parsed and check for any obvious issues
from html.parser import HTMLParser

class SimpleChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.tag_stack = []
        self.div_ids = set()

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag in ['div', 'section', 'header', 'footer']:
            self.tag_stack.append(tag)
        if tag == 'div' and 'id' in attrs_dict:
            self.div_ids.add(attrs_dict['id'])

    def handle_endtag(self, tag):
        if tag in ['div', 'section', 'header', 'footer']:
            if self.tag_stack and self.tag_stack[-1] == tag:
                self.tag_stack.pop()
            else:
                self.errors.append(f"Unexpected closing tag: {tag}")

with open('/app/output/final_report.html', 'r') as f:
    html = f.read()

checker = SimpleChecker()
checker.feed(html)

print(f"HTML parsing errors: {len(checker.errors)}")
for err in checker.errors[:10]:
    print(f"  {err}")

print(f"\nDiv IDs found: {len(checker.div_ids)}")
chart_divs = [d for d in checker.div_ids if d.startswith('chart-')]
print(f"Chart divs: {len(chart_divs)}")
for d in chart_divs:
    print(f"  {d}")

